$ErrorActionPreference = 'Stop'
$Root = 'C:\iterate-hackathon\simulator-check'
New-Item -ItemType Directory -Force -Path $Root | Out-Null
[IO.File]::WriteAllBytes((Join-Path $Root 'check_reference.py'), [Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $Root 'reference_cases.json'), [Convert]::FromBase64String(''))
& 'C:\chemsep-benchmark\venv\Scripts\python.exe' (Join-Path $Root 'check_reference.py') --cases (Join-Path $Root 'reference_cases.json') --out (Join-Path $Root 'results.json')
if ($LASTEXITCODE -ne 0) { throw 'Reference checks failed; inspect results.json' }
